static char* read_all(void) {
    size_t cap = 1 << 16, len = 0;
    char* buf = malloc(cap);
    for (;;) {
        if (len + 1 >= cap) buf = realloc(buf, cap *= 2);
        size_t r = fread(buf + len, 1, cap - len - 1, stdin);
        if (r == 0) break;
        len += r;
    }
    buf[len] = '\0';
    return buf;
}

static char** g_lines;
static int g_count;

static char* line(int i) {
