}

static int* parse_ints(const char* s, int* n) {
    int cap = 16;
    int* out = malloc(cap * sizeof(int));
    char* end;
    *n = 0;
    for (;;) {
        long v = strtol(s, &end, 10);
        if (end == s) break;
        if (*n == cap) out = realloc(out, (cap *= 2) * sizeof(int));
        out[(*n)++] = (int)v;
        s = end;
    }
    return out;
}

int main(void) {
    char* input = read_all();
    int cap = 8;
    g_lines = malloc(cap * sizeof(char*));
    for (char* p = input;;) {
        if (g_count == cap) g_lines = realloc(g_lines, (cap *= 2) * sizeof(char*));
        g_lines[g_count++] = p;
        char* nl = strchr(p, '\n');
        size_t n = nl ? (size_t)(nl - p) : strlen(p);
        if (n && p[n - 1] == '\r') p[n - 1] = '\0';
        if (!nl) break;
        *nl = '\0';
        p = nl + 1;
