func atoi(s string) int {
	v, _ := strconv.Atoi(s)
	return v
}

func parseInts(s string) []int {
	f := strings.Fields(s)
	out := make([]int, len(f))
	for i, w := range f {
		out[i] = atoi(w)
	}
	return out
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	lines := strings.Split(strings.ReplaceAll(string(data), "\r", ""), "\n")
	line := func(i int) string {
		if i < len(lines) {
			return lines[i]
		}
		return ""
	}
	nums := parseInts(line(0))
	result := solve(nums)
	fmt.Println(result)
