from typing import List


def solve(nums: List[int]) -> int:
    # Return the length of the longest strictly increasing subsequence.
    tails = []
    for x in nums:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)


